// App configuration — generated by scripts/setup-supabase.sh (safe to edit by hand).
// Safe to commit: the Supabase publishable/anon key is public by design —
// data is protected by Row Level Security policies in the database, not by hiding this key.
// Leave supabaseUrl empty to run in local-only mode (no login, data stays in this browser).
window.APP_CONFIG = {
  // Supabase → Project Settings → API Keys / Data API
  supabaseUrl: "https://koqetdjtgecjpmckzeld.supabase.co",
  supabaseAnonKey: "sb_publishable_ZCLbBbPTbhvwGDqOn7kjAA_JmQX_L7e",   // publishable/anon key — NEVER the secret/service_role key

  // OAuth providers shown on the login screen. Each must also be enabled in
  // Supabase → Authentication → Sign In / Providers. Supported here: "google", "apple", "github".
  authProviders: ["google"],

  // false = Google only: hides the email-code form (no custom SMTP needed).
  emailLogin: false,

  // false = the email-code form never creates accounts (only used when emailLogin is true).
  allowEmailSignUp: false
};
